CREATE TYPE public.app_role AS ENUM ('admin', 'faturamento', 'remessa');
CREATE TABLE public.profiles (id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, email text NOT NULL, display_name text NOT NULL DEFAULT '', active boolean NOT NULL DEFAULT true);
GRANT SELECT, UPDATE ON public.profiles TO authenticated;
GRANT ALL ON public.profiles TO service_role;
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.user_roles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, role public.app_role NOT NULL, UNIQUE(user_id, role));
GRANT SELECT ON public.user_roles TO authenticated;
GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.account_invitations (email text PRIMARY KEY, display_name text NOT NULL, role public.app_role NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
GRANT ALL ON public.account_invitations TO service_role;
ALTER TABLE public.account_invitations ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.has_role(_user_id uuid, _role public.app_role) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles r JOIN public.profiles p ON p.id=r.user_id WHERE r.user_id=_user_id AND r.role=_role AND p.active) $$;
REVOKE ALL ON FUNCTION public.has_role(uuid, public.app_role) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.has_role(uuid, public.app_role) TO authenticated, service_role;
CREATE POLICY profile_read ON public.profiles FOR SELECT TO authenticated USING(id=auth.uid() OR public.has_role(auth.uid(),'admin'));
CREATE POLICY profile_admin_update ON public.profiles FOR UPDATE TO authenticated USING(public.has_role(auth.uid(),'admin') AND id<>auth.uid()) WITH CHECK(public.has_role(auth.uid(),'admin') AND id<>auth.uid());
CREATE POLICY role_read ON public.user_roles FOR SELECT TO authenticated USING(user_id=auth.uid() OR public.has_role(auth.uid(),'admin'));
CREATE FUNCTION public.create_platform_account() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE invitation public.account_invitations; assigned_role public.app_role; assigned_name text; BEGIN
SELECT * INTO invitation FROM public.account_invitations WHERE email=lower(NEW.email) FOR UPDATE;
IF lower(NEW.email)='admin@admind.com' THEN assigned_role:='admin'; assigned_name:='Administrador';
ELSIF invitation.email IS NOT NULL THEN assigned_role:=invitation.role; assigned_name:=invitation.display_name;
ELSE RAISE EXCEPTION 'Cadastro disponível somente por convite do administrador'; END IF;
INSERT INTO public.profiles(id,email,display_name) VALUES(NEW.id,lower(NEW.email),assigned_name);
INSERT INTO public.user_roles(user_id,role) VALUES(NEW.id,assigned_role);
DELETE FROM public.account_invitations WHERE email=lower(NEW.email);
RETURN NEW; END $$;
REVOKE ALL ON FUNCTION public.create_platform_account() FROM PUBLIC;
CREATE TRIGGER platform_account_created AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.create_platform_account();
REVOKE ALL ON public.app_users FROM anon, authenticated;
COMMENT ON TABLE public.app_users IS 'DEPRECATED: insecure legacy login replaced by Auth, profiles and user_roles';
DROP POLICY IF EXISTS "auth all loads" ON public.cargo_loads;
DROP POLICY IF EXISTS "auth all products" ON public.cargo_products;
DROP POLICY IF EXISTS "auth all history" ON public.cargo_history;
DROP POLICY IF EXISTS "auth all contacts" ON public.cte_contacts;
DROP POLICY IF EXISTS "ops all loads" ON public.cargo_loads;
DROP POLICY IF EXISTS "ops all products" ON public.cargo_products;
DROP POLICY IF EXISTS "ops all history" ON public.cargo_history;
DROP POLICY IF EXISTS "ops all contacts" ON public.cte_contacts;
REVOKE ALL ON public.cargo_loads, public.cargo_products, public.cargo_history, public.cte_contacts FROM anon;
CREATE POLICY loads_read ON public.cargo_loads FOR SELECT TO authenticated USING(public.has_role(auth.uid(),'admin') OR public.has_role(auth.uid(),'faturamento') OR public.has_role(auth.uid(),'remessa'));
CREATE POLICY loads_import ON public.cargo_loads FOR INSERT TO authenticated WITH CHECK(public.has_role(auth.uid(),'admin') OR public.has_role(auth.uid(),'remessa'));
CREATE POLICY loads_process ON public.cargo_loads FOR UPDATE TO authenticated USING(public.has_role(auth.uid(),'admin') OR public.has_role(auth.uid(),'faturamento')) WITH CHECK(public.has_role(auth.uid(),'admin') OR public.has_role(auth.uid(),'faturamento'));
CREATE POLICY products_read ON public.cargo_products FOR SELECT TO authenticated USING(public.has_role(auth.uid(),'admin') OR public.has_role(auth.uid(),'faturamento') OR public.has_role(auth.uid(),'remessa'));
CREATE POLICY products_import ON public.cargo_products FOR INSERT TO authenticated WITH CHECK(public.has_role(auth.uid(),'admin') OR public.has_role(auth.uid(),'remessa'));
CREATE POLICY history_read ON public.cargo_history FOR SELECT TO authenticated USING(public.has_role(auth.uid(),'admin') OR public.has_role(auth.uid(),'faturamento') OR public.has_role(auth.uid(),'remessa'));
CREATE POLICY history_insert ON public.cargo_history FOR INSERT TO authenticated WITH CHECK(public.has_role(auth.uid(),'admin') OR public.has_role(auth.uid(),'faturamento') OR public.has_role(auth.uid(),'remessa'));
CREATE POLICY contacts_read ON public.cte_contacts FOR SELECT TO authenticated USING(public.has_role(auth.uid(),'admin') OR public.has_role(auth.uid(),'faturamento') OR public.has_role(auth.uid(),'remessa'));
CREATE POLICY contacts_insert ON public.cte_contacts FOR INSERT TO authenticated WITH CHECK(public.has_role(auth.uid(),'admin') OR public.has_role(auth.uid(),'faturamento'));